{
  "name": "open-magi-opencode",
  "version": "0.2.0",
  "description": "OpenCode Magi deliberation loop plugin and setup CLI",
  "type": "module",
  "license": "MIT",
  "homepage": "https://github.com/ladiossoop5star/open_magi#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ladiossoop5star/open_magi.git"
  },
  "bugs": {
    "url": "https://github.com/ladiossoop5star/open_magi/issues"
  },
  "main": "./index.js",
  "exports": {
    ".": "./index.js",
    "./setup": "./lib/setup.js"
  },
  "pi": {
    "extensions": [
      "./adapters/pi/extension.js"
    ],
    "skills": [
      "./adapters/pi/skills"
    ]
  },
  "bin": {
    "open-magi": "bin/open-magi.js"
  },
  "files": [
    "bin",
    "index.js",
    "lib",
    "skills",
    "README.md",
    "README.zh-TW.md",
    "LICENSE",
    "adapters/pi"
  ],
  "scripts": {
    "postinstall": "node bin/postinstall.js",
    "test": "node --test test/package.test.mjs test/plugin.test.mjs test/setup.test.mjs test/pi-adapter.test.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "plugin",
    "magi",
    "deliberation",
    "multi-agent"
  ]
}

